 58	SWAPPED_PIXEL = """#elif TGL_FEATURE_RENDER_BITS == 16
 59	/* The canvas keeps RGB565 with its bytes swapped (display order). */
 60	#define TGL_SWAP16(v) ((((v) << 8) | ((v) >> 8)) & 0xFFFF)
 61	#define RGB_TO_PIXEL(r,g,b) \\
 62	\tTGL_SWAP16( COLOR_R_GET16(r) | COLOR_G_GET16(g) | COLOR_B_GET16(b)  )
 63	#endif
 64	"""
