 69	void glshim_note_box(GLint x0, GLint y0, GLint x1, GLint y1);
 70	void glshim_clear(ZBuffer* zb, GLint clear_z, GLint z, GLint clear_color, GLint r, GLint g, GLint b);
 71	"""
