 76		GLint ly = p0->zp.y < p1->zp.y ? p0->zp.y : p1->zp.y;
 77		GLint hy = p0->zp.y < p1->zp.y ? p1->zp.y : p0->zp.y;
 78		if (p2->zp.x < lx) lx = p2->zp.x;
 79		if (p2->zp.x > hx) hx = p2->zp.x;
 80		if (p2->zp.y < ly) ly = p2->zp.y;
 81		if (p2->zp.y > hy) hy = p2->zp.y;
 82		glshim_note_box(lx, ly, hx, hy);
 83	}
