 88		if (p0->clip_code == 0) {
 89			GLint m = (GLint)gl_get_context()->zb->pointsize + 1;
 90			glshim_note_box(p0->zp.x - m, p0->zp.y - m, p0->zp.x + m, p0->zp.y + m);
 91		}
