 94	DIRTY_LINE = """void gl_draw_line(GLVertex* p1, GLVertex* p2) {
 95		if ((p1->clip_code | p2->clip_code) == 0) {
 96			GLint lx = p1->zp.x < p2->zp.x ? p1->zp.x : p2->zp.x;
 97			GLint hx = p1->zp.x < p2->zp.x ? p2->zp.x : p1->zp.x;
 98			GLint ly = p1->zp.y < p2->zp.y ? p1->zp.y : p2->zp.y;
 99			GLint hy = p1->zp.y < p2->zp.y ? p2->zp.y : p1->zp.y;
100			glshim_note_box(lx - 1, ly - 1, hx + 1, hy + 1);
101		} else { /* clipped: it may reach anywhere */
102			glshim_note_box(0, 0, 100000, 100000);
103		}
104	"""
105	
106	# TinyGL snaps every vertex to a whole pixel before it draws a line, so a line
107	# that moves a little jumps a whole pixel somewhere along its length. The
108	# vertex transforms now keep the fractional position (zp.fx, zp.fy), and when a
109	# hack enables GL_LINE_SMOOTH the line is drawn with Wu's algorithm: each step
110	# along the major axis shares one pixel of brightness between the two nearest
111	# pixels across it, blended over what is already there.
112	AA_LINE = """#include <math.h>
113	
114	#if TGL_FEATURE_RENDER_BITS == 16
115	static GLint zb_aa_floor(GLfloat f) {
116		GLint i = (GLint)f;
117		return ((GLfloat)i > f) ? i - 1 : i;
118	}
119	
120	static void zb_aa_plot(ZBuffer* zb, GLint x, GLint y, GLint z, GLint cover, GLint use_z, GLint sr, GLint sg, GLint sb) {
121		GLushort* pz;
122		PIXEL* pp;
123		GLint zz, v, dr, dg, db;
124		if (cover <= 0 || x < 0 || y < 0 || x >= zb->xsize || y >= zb->ysize) return;
125		if (cover > 256) cover = 256;
126		pz = zb->zbuf + (y * zb->xsize + x);
127		zz = z >> ZB_POINT_Z_FRAC_BITS;
128		if (use_z && zb->depth_test && zz < (GLint)*pz) return;
129		pp = (PIXEL*)((GLbyte*)zb->pbuf + zb->linesize * y + x * PSZB);
130		v = TGL_SWAP16(*pp);
131		dr = (v >> 11) & 31;
132		dg = (v >> 5) & 63;
133		db = v & 31;
134		dr = (sr * cover + dr * (256 - cover) + 128) >> 8;
135		dg = (sg * cover + dg * (256 - cover) + 128) >> 8;
136		db = (sb * cover + db * (256 - cover) + 128) >> 8;
137		*pp = TGL_SWAP16((dr << 11) | (dg << 5) | db);
138		if (use_z && zb->depth_write) *pz = zz;
139	}
140	
141	/* Returns 0 for a line it cannot draw (colour interpolated along it, or a
142	 * vertex whose fractional position was not recorded), which the caller then
143	 * draws plain. */
144	static GLint ZB_line_aa(ZBuffer* zb, ZBufferPoint* p1, ZBufferPoint* p2, GLint use_z) {
145		GLfloat x0 = p1->fx, y0 = p1->fy, x1 = p2->fx, y1 = p2->fy;
146		GLfloat z0 = (GLfloat)p1->z, dz = (GLfloat)(p2->z - p1->z);
147		GLfloat dx, dy, grad, zinc, pos, z, scale, tmp;
148		GLint colour, v, sr, sg, sb, steep, i, i0, i1, row, hi, lo;
149	
150		colour = RGB_TO_PIXEL(p1->r, p1->g, p1->b);
151		if (RGB_TO_PIXEL(p2->r, p2->g, p2->b) != colour) return 0;
152		if (fabsf(x0 - (GLfloat)p1->x) >= 1.0f || fabsf(y0 - (GLfloat)p1->y) >= 1.0f) return 0;
153		if (fabsf(x1 - (GLfloat)p2->x) >= 1.0f || fabsf(y1 - (GLfloat)p2->y) >= 1.0f) return 0;
154		v = TGL_SWAP16(colour);
155		sr = (v >> 11) & 31;
156		sg = (v >> 5) & 63;
157		sb = v & 31;
158	
159		steep = fabsf(y1 - y0) > fabsf(x1 - x0);
160		if (steep) {
161			tmp = x0; x0 = y0; y0 = tmp;
162			tmp = x1; x1 = y1; y1 = tmp;
163		}
164		if (x1 < x0) {
165			tmp = x0; x0 = x1; x1 = tmp;
166			tmp = y0; y0 = y1; y1 = tmp;
167			z0 = (GLfloat)p2->z;
168			dz = -dz;
169		}
170		dx = x1 - x0;
171		dy = y1 - y0;
172		grad = 0.0f;
173		zinc = 0.0f;
174		scale = 1.0f;
175		i0 = zb_aa_floor(x0 - 0.5f) + 1;
176		i1 = zb_aa_floor(x1 - 0.5f);
177		if (i1 < i0 || dx < 1e-4f) {
178			/* shorter than the gap between two pixel centres: its midpoint's pixel */
179			i0 = i1 = zb_aa_floor((x0 + x1) * 0.5f);
180			pos = (y0 + y1) * 0.5f - 0.5f;
181			z = z0 + dz * 0.5f;
182		} else {
183			grad = dy / dx;
184			zinc = dz / dx;
185			scale = sqrtf(1.0f + grad * grad);
186			pos = y0 + ((GLfloat)i0 + 0.5f - x0) * grad - 0.5f;
187			z = z0 + ((GLfloat)i0 + 0.5f - x0) * zinc;
188		}
189		/* The brightness of a pixel is its share of a one pixel wide line. */
190		for (i = i0; i <= i1; i++) {
191			row = zb_aa_floor(pos);
192			hi = (GLint)((pos - (GLfloat)row) * 256.0f * scale + 0.5f);
193			lo = (GLint)((1.0f - (pos - (GLfloat)row)) * 256.0f * scale + 0.5f);
194			if (steep) {
195				zb_aa_plot(zb, row, i, (GLint)z, lo, use_z, sr, sg, sb);
196				zb_aa_plot(zb, row + 1, i, (GLint)z, hi, use_z, sr, sg, sb);
197			} else {
198				zb_aa_plot(zb, i, row, (GLint)z, lo, use_z, sr, sg, sb);
199				zb_aa_plot(zb, i, row + 1, (GLint)z, hi, use_z, sr, sg, sb);
200			}
201			pos += grad;
202			z += zinc;
203		}
204		return 1;
205	}
206	#else
207	static GLint ZB_line_aa(ZBuffer* zb, ZBufferPoint* p1, ZBufferPoint* p2, GLint use_z) {
208		(void)zb; (void)p1; (void)p2; (void)use_z;
209		return 0;
210	}
211	#endif
212	
213	"""
214	
215	# Two things a hack asks of filled triangles that TinyGL stores but ignores.
216	#
217	# Polygon offset: glPolygonOffset and GL_POLYGON_OFFSET_FILL are recorded and
218	# nothing reads them, so a line drawn on the edge of its own filled polygon
219	# fights it for the depth test. The offset is factor * the polygon's steepest
220	# depth slope + units * the smallest depth step, pushed away from the viewer.
221	# The rasteriser also snaps a polygon's vertices to whole pixels, so its depth
222	# at a pixel can be wrong by a pixel's slope in each direction, which the
223	# hack's own numbers assume away: when an offset is asked for, that margin
224	# (|dz/dx| + |dz/dy|) is added. Without it the polygon still erased a few
225	# percent of its own line, a different few each frame, which flickered.
226	#
227	# Alpha: TinyGL has no alpha, which is what GL's SRC_ALPHA / ONE_MINUS_SRC_ALPHA
228	# calls an alpha of 1, an opaque fill. Its own blend adds the colours, and reads
229	# our byte-swapped pixels as if they were not swapped.
230	FILL_TRIANGLE = """#include <math.h>
231	static void gl_draw_triangle_fill_plain(GLVertex* p0, GLVertex* p1, GLVertex* p2);
232	
233	void gl_draw_triangle_fill(GLVertex* p0, GLVertex* p1, GLVertex* p2) {
234		GLContext* c = gl_get_context();
235		GLint blend = c->zb->enable_blend;
236		GLint bias = 0;
237		if (blend && c->zb->sfactor == GL_SRC_ALPHA && c->zb->dfactor == GL_ONE_MINUS_SRC_ALPHA)
238			c->zb->enable_blend = 0;
239		if (c->offset_states & TGL_OFFSET_FILL) {
240			GLfloat ax = (GLfloat)(p1->zp.x - p0->zp.x), ay = (GLfloat)(p1->zp.y - p0->zp.y), az = (GLfloat)(p1->zp.z - p0->zp.z);
241			GLfloat bx = (GLfloat)(p2->zp.x - p0->zp.x), by = (GLfloat)(p2->zp.y - p0->zp.y), bz = (GLfloat)(p2->zp.z - p0->zp.z);
242			GLfloat det = ax * by - ay * bx;
243			GLfloat slope = 0.0f, snap = 0.0f;
244			if (det != 0.0f) {
245				GLfloat dzdx = fabsf((az * by - ay * bz) / det);
246				GLfloat dzdy = fabsf((ax * bz - az * bx) / det);
247				slope = dzdx > dzdy ? dzdx : dzdy;
248				snap = (c->offset_factor != 0.0f || c->offset_units != 0.0f) ? dzdx + dzdy : 0.0f;
249			}
250			bias = (GLint)(c->offset_factor * slope + snap + c->offset_units * (GLfloat)(1 << ZB_POINT_Z_FRAC_BITS));
251		}
252		if (bias) {
253			p0->zp.z -= bias;
254			p1->zp.z -= bias;
255			p2->zp.z -= bias;
256		}
257		gl_draw_triangle_fill_plain(p0, p1, p2);
258		if (bias) {
259			p0->zp.z += bias;
260			p1->zp.z += bias;
261			p2->zp.z += bias;
262		}
263		c->zb->enable_blend = blend;
264	}
265	
266	static void gl_draw_triangle_fill_plain(GLVertex* p0, GLVertex* p1, GLVertex* p2) {
267	"""
268	
