120	   120	static void zb_aa_plot(ZBuffer* zb, GLint x, GLint y, GLint z, GLint cover, GLint use_z, GLint sr, GLint sg, GLint sb) {
121	   121		GLushort* pz;
122	   122		PIXEL* pp;
123	   123		GLint zz, v, dr, dg, db;
124	   124		if (cover <= 0 || x < 0 || y < 0 || x >= zb->xsize || y >= zb->ysize) return;
125	   125		if (cover > 256) cover = 256;
126	   126		pz = zb->zbuf + (y * zb->xsize + x);
127	   127		zz = z >> ZB_POINT_Z_FRAC_BITS;
128	   128		if (use_z && zb->depth_test && zz < (GLint)*pz) return;
129	   129		pp = (PIXEL*)((GLbyte*)zb->pbuf + zb->linesize * y + x * PSZB);
130	   130		v = TGL_SWAP16(*pp);
131	   131		dr = (v >> 11) & 31;
132	   132		dg = (v >> 5) & 63;
133	   133		db = v & 31;
134	   134		dr = (sr * cover + dr * (256 - cover) + 128) >> 8;
135	   135		dg = (sg * cover + dg * (256 - cover) + 128) >> 8;
136	   136		db = (sb * cover + db * (256 - cover) + 128) >> 8;
137	   137		*pp = TGL_SWAP16((dr << 11) | (dg << 5) | db);
138	   138		if (use_z && zb->depth_write) *pz = zz;
139	   139	}
