141	   141	/* Returns 0 for a line it cannot draw (colour interpolated along it, or a
142	   142	 * vertex whose fractional position was not recorded), which the caller then
143	   143	 * draws plain. */
144	   144	static GLint ZB_line_aa(ZBuffer* zb, ZBufferPoint* p1, ZBufferPoint* p2, GLint use_z) {
145	   145		GLfloat x0 = p1->fx, y0 = p1->fy, x1 = p2->fx, y1 = p2->fy;
146	   146		GLfloat z0 = (GLfloat)p1->z, dz = (GLfloat)(p2->z - p1->z);
147	   147		GLfloat dx, dy, grad, zinc, pos, z, scale, tmp;
148	   148		GLint colour, v, sr, sg, sb, steep, i, i0, i1, row, hi, lo;
149	   149	
150	   150		colour = RGB_TO_PIXEL(p1->r, p1->g, p1->b);
151	   151		if (RGB_TO_PIXEL(p2->r, p2->g, p2->b) != colour) return 0;
152	   152		if (fabsf(x0 - (GLfloat)p1->x) >= 1.0f || fabsf(y0 - (GLfloat)p1->y) >= 1.0f) return 0;
153	   153		if (fabsf(x1 - (GLfloat)p2->x) >= 1.0f || fabsf(y1 - (GLfloat)p2->y) >= 1.0f) return 0;
154	   154		v = TGL_SWAP16(colour);
155	   155		sr = (v >> 11) & 31;
156	   156		sg = (v >> 5) & 63;
157	   157		sb = v & 31;
158	   158	
159	   159		steep = fabsf(y1 - y0) > fabsf(x1 - x0);
160	   160		if (steep) {
161	   161			tmp = x0; x0 = y0; y0 = tmp;
162	   162			tmp = x1; x1 = y1; y1 = tmp;
163	   163		}
164	   164		if (x1 < x0) {
165	   165			tmp = x0; x0 = x1; x1 = tmp;
166	   166			tmp = y0; y0 = y1; y1 = tmp;
167	   167			z0 = (GLfloat)p2->z;
168	   168			dz = -dz;
169	   169		}
170	   170		dx = x1 - x0;
171	   171		dy = y1 - y0;
172	   172		grad = 0.0f;
173	   173		zinc = 0.0f;
174	   174		scale = 1.0f;
175	   175		i0 = zb_aa_floor(x0 - 0.5f) + 1;
176	   176		i1 = zb_aa_floor(x1 - 0.5f);
177	   177		if (i1 < i0 || dx < 1e-4f) {
178	   178			/* shorter than the gap between two pixel centres: its midpoint's pixel */
179	   179			i0 = i1 = zb_aa_floor((x0 + x1) * 0.5f);
180	   180			pos = (y0 + y1) * 0.5f - 0.5f;
181	   181			z = z0 + dz * 0.5f;
182	   182		} else {
183	   183			grad = dy / dx;
184	   184			zinc = dz / dx;
185	   185			scale = sqrtf(1.0f + grad * grad);
186	   186			pos = y0 + ((GLfloat)i0 + 0.5f - x0) * grad - 0.5f;
187	   187			z = z0 + ((GLfloat)i0 + 0.5f - x0) * zinc;
188	   188		}
189	   189		/* The brightness of a pixel is its share of a one pixel wide line. */
190	   190		for (i = i0; i <= i1; i++) {
191	   191			row = zb_aa_floor(pos);
192	   192			hi = (GLint)((pos - (GLfloat)row) * 256.0f * scale + 0.5f);
193	   193			lo = (GLint)((1.0f - (pos - (GLfloat)row)) * 256.0f * scale + 0.5f);
194	   194			if (steep) {
195	   195				zb_aa_plot(zb, row, i, (GLint)z, lo, use_z, sr, sg, sb);
196	   196				zb_aa_plot(zb, row + 1, i, (GLint)z, hi, use_z, sr, sg, sb);
197	   197			} else {
198	   198				zb_aa_plot(zb, i, row, (GLint)z, lo, use_z, sr, sg, sb);
199	   199				zb_aa_plot(zb, i, row + 1, (GLint)z, hi, use_z, sr, sg, sb);
200	   200			}
201	   201			pos += grad;
202	   202			z += zinc;
203	   203		}
204	   204		return 1;
205	   205	}
206	   206	#else
207	   207	static GLint ZB_line_aa(ZBuffer* zb, ZBufferPoint* p1, ZBufferPoint* p2, GLint use_z) {
