236	   236		GLint bias = 0;
237	   237		if (blend && c->zb->sfactor == GL_SRC_ALPHA && c->zb->dfactor == GL_ONE_MINUS_SRC_ALPHA)
238	   238			c->zb->enable_blend = 0;
239	   239		if (c->offset_states & TGL_OFFSET_FILL) {
240	   240			GLfloat ax = (GLfloat)(p1->zp.x - p0->zp.x), ay = (GLfloat)(p1->zp.y - p0->zp.y), az = (GLfloat)(p1->zp.z - p0->zp.z);
