242	   242			GLfloat det = ax * by - ay * bx;
243	   243			GLfloat slope = 0.0f, snap = 0.0f;
244	   244			if (det != 0.0f) {
245	   245				GLfloat dzdx = fabsf((az * by - ay * bz) / det);
