550	+#include "runner/te_sync.h"
551	+
552	+void te_sync_init(TeSync *s, uint32_t offset_us, uint32_t timeout_us) {
553	+  s->last_rise_us = 0;
554	+  s->period_us = 0;
555	+  s->rises = 0;
556	+  s->offset_us = offset_us;
557	+  s->timeout_us = timeout_us;
558	+}
559	+
560	+void TE_SYNC_ISR te_sync_edge(TeSync *s, uint32_t now_us, int level) {
561	+  if (!level) return;
562	+  if (s->rises == 0) {
563	+    s->last_rise_us = now_us;
564	+    s->rises = 1;
565	+    return;
566	+  }
567	+  const uint32_t gap = now_us - s->last_rise_us;
568	+  if (gap < TE_SYNC_MIN_PERIOD_US) return; /* a glitch: keep the true edge */
569	+
570	+  const uint32_t period = s->period_us;
571	+  if (gap <= TE_SYNC_MAX_PERIOD_US) {
572	+    /* an eighth of the way to each new gap, so a slow drift is followed */
573	+    if (!period)
574	+      s->period_us = gap;
575	+    else if (gap >= period)
576	+      s->period_us = period + (gap - period) / 8;
577	+    else
578	+      s->period_us = period - (period - gap) / 8;
579	+    s->rises = 2;
580	+  } else if (period) {
581	+    /* Edges the interrupt missed leave a whole number of periods; anything
582	+     * else is a restart, and the period is learnt again. */
583	+    const uint32_t k = (gap + period / 2) / period;
584	+    const uint32_t off = gap > k * period ? gap - k * period : k * period - gap;
585	+    if (k < 2 || off > period / 16) {
586	+      s->period_us = 0;
587	+      s->rises = 1;
588	+    }
589	+  } else {
590	+    s->rises = 1;
591	+  }
592	+  s->last_rise_us = now_us;
593	+}
594	+
595	+uint32_t te_sync_period_us(const TeSync *s) { return s->period_us; }
596	+
597	+uint32_t te_sync_wait_us(const TeSync *s, uint32_t now_us) {
598	+  const uint32_t period = s->period_us;
599	+  if (!period) return 0;
600	+  uint32_t since = now_us - s->last_rise_us;
601	+  if ((int32_t)since < 0) since = 0; /* the edge landed just after now was read */
602	+  if (since > s->timeout_us) return 0;
603	+  const uint32_t into = since % period;
604	+  const uint32_t offset = s->offset_us % period;
605	+  return into <= offset ? offset - into : period - into + offset;
606	+}
