diff --git a/firmware/src/x11shim/easing.c b/firmware/src/x11shim/easing.c
new file mode 100644
index 0000000..d31eb9e
--- /dev/null
+++ b/firmware/src/x11shim/easing.c
@@ -0,0 +1,24 @@
+#include "easing.h"
+
+#include <math.h>
+#include <stdlib.h>
+
+/* The sines run in single precision: the S3's FPU is single-precision only,
+ * so a double cos is a software routine, and a hack calls this for every row
+ * of every frame. */
+#define PI_F 3.14159265358979323846f
+
+double ease(easing_function fn, double x) {
+  float t = (float)x;
+  switch (fn) {
+    case EASE_NONE:
+      return x;
+    case EASE_IN_SINE:
+      return 1.0f - cosf(t * PI_F / 2.0f);
+    case EASE_OUT_SINE:
+      return sinf(t * PI_F / 2.0f);
+    case EASE_IN_OUT_SINE:
+      return -(cosf(PI_F * t) - 1.0f) / 2.0f;
+  }
+  abort();
+}
