    39	static const char *find_in(const char *const *list, const char *name) {
    40	  size_t len = strlen(name);
    41	  for (const char *const *p = list; p && *p; p++) {
    42	    const char *s = *p;
    43	    if (*s == '.' || *s == '*') s++;
    44	    const char *v = value_if_named(s, name, len);
    45	    if (v) return v;
    46	  }
    47	  for (const char *const *p = list; p && *p; p++) {
    48	    const char *dot = strchr(*p, '.');
    49	    const char *colon = strchr(*p, ':');
    50	    if (!dot || dot == *p || !colon || dot > colon || **p == '*') continue;
    51	    const char *v = value_if_named(dot + 1, name, len);
    52	    if (v) return v;
    53	  }
    54	  return NULL;
    55	}
